from sys import stdin, stdout
import math

MOD = 10**9 + 7

def binpow(a, b):
    res = 1
    while b > 0:
        if b & 1:
            res = res * a % MOD
        a = a * a % MOD
        b >>= 1
    return res

def inv(n):
    return binpow(n, MOD - 2)

def solve():
    n, k = map(int, stdin.readline().split())
    weights = list(map(int, stdin.readline().split()))

    total_weight = sum(weights)
    factorial = [1] * (n + 1)
    inverse_factorial = [1] * (n + 1)

