MOD = 10**9 + 7

def mod_inv(x):
    return pow(x, MOD - 2, MOD)

def binom(n, k):
    if k > n:
        return 0
    return factorial(n) * mod_inv(factorial(k)) % MOD * mod_inv(factorial(n - k)) % MOD

def solve():
