from math import factorial

MOD = 10**9 + 7

def stirling_second_kind(n, k):
    if n == k == 0:
        return 1
    if n == 0 or k == 0:
        return 0
    return k * stirling_second_kind(n - 1, k) + stirling_second_kind(n - 1, k - 1)

def power(x, y):
    result = 1
    while y > 0:
        if y % 2 == 1:
            result = (result * x) % MOD
        x = (x * x) % MOD
        y //= 2
    return result

def sum_of_weights(n, k, weights):
    total_sum = 0
    for i in range(k):
        sign = (-1)**i
        coeff = sign * stirling_second_kind(n, i)
        coeff *= power(i + 1, n)
        coeff %= MOD
        for j in range(n):
            coeff *= weights[j]
            coeff %= MOD
        total_sum += coeff
        total_sum %= MOD
    return total_sum

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    weights = list(map(int, data[2:]))

    result = sum_of_weights(n, k, weights)
    print(result)

if __name__ == "__main__":
    main()
